
// troca de versão: a tela "hoje" é estática; os atalhos da proposta só valem quando ela está visível
(function(){
  const vh=document.getElementById('viewHoje'),vp=document.getElementById('viewProposta');
  const bh=document.getElementById('vHoje'),bp=document.getElementById('vProp');
  window.__view='proposta';
  function show(v){window.__view=v;vh.hidden=v!=='hoje';vp.hidden=v!=='proposta';
    bh.setAttribute('aria-pressed',v==='hoje');bp.setAttribute('aria-pressed',v==='proposta');
    document.title='Ponta de Gôndola: '+(v==='hoje'?'Hoje':'Proposta');window.scrollTo(0,0);
    if(v==='proposta'&&window.draw)draw()}
  bh.onclick=()=>show('hoje');bp.onclick=()=>show('proposta');
  window.addEventListener('keydown',e=>{
    if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
    if(e.key==='v'||e.key==='V'){show(window.__view==='hoje'?'proposta':'hoje');e.stopImmediatePropagation();return}
    if(window.__view!=='proposta')e.stopImmediatePropagation();
  },true);
  window.addEventListener('paste',e=>{if(window.__view!=='proposta')e.stopImmediatePropagation()},true);
  show(location.hash==='#hoje'?'hoje':'proposta');
})();

const SAMPLE="data:image/png;base64,";
const $=id=>document.getElementById(id);
const cv=$('cv'), ctx=cv.getContext('2d');
const store={get(k,d){return d},set(){}}; // proposta: tudo em memória

let tipos=store.get('pg_tipos',[
  {nome:'Gôndola Alta',cor:'#ffd100',frente:25,prof:15},
  {nome:'Gôndola Baixa',cor:'#8fd14f',frente:25,prof:15},
  {nome:'Checkout',cor:'#4aa3ff',frente:15,prof:12},
]);
let img=null, imgData=null, W=1000, H=666;
let gondolas=[], pontas=[], sel=null, addMode=false, orientMode='auto', nextId=1;
let zoom=1;

function toast(m){const t=$('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),1600)}
function tipoOf(p){return tipos[p.tipo]||tipos[0]}
// escala para o ERP
function k(){const e=+$('erpW').value||W;return e/W}
function erp(p){const s=k(),ox=+$('offX').value||0,oy=+$('offY').value||0;
  return {X:Math.round(p.x*s+ox),Y:Math.round(p.y*s+oy),H:Math.round(p.h*s),W:Math.round(p.w*s)}}
function fromErp(v){const s=k(),ox=+$('offX').value||0,oy=+$('offY').value||0;
  return {x:(v.X-ox)/s,y:(v.Y-oy)/s,h:v.H/s,w:v.W/s}}
function sizeFor(tipoIdx,orient){const t=tipos[tipoIdx]||tipos[0];
  return orient==='V'?{w:t.frente,h:t.prof}:{w:t.prof,h:t.frente}}

// ---------- imagem ----------
function loadImage(src,cb){const im=new Image();im.onload=()=>{img=im;W=im.naturalWidth;H=im.naturalHeight;
  const oc=document.createElement('canvas');oc.width=W;oc.height=H;const o=oc.getContext('2d');o.drawImage(im,0,0);
  imgData=o.getImageData(0,0,W,H).data;$('erpW').value=W;gondolas=[];pontas=[];sel=null;selG=null;resize();updScale();cb&&cb();};im.src=src}
function readFile(f){if(!f||!f.type.startsWith('image/'))return;const r=new FileReader();r.onload=()=>loadImage(r.result,()=>{detect();toast('Planta carregada')});r.readAsDataURL(f)}
$('file').onchange=e=>readFile(e.target.files[0]);
const stage=$('stage');
stage.addEventListener('dragover',e=>{e.preventDefault();stage.classList.add('drag')});
stage.addEventListener('dragleave',()=>stage.classList.remove('drag'));
stage.addEventListener('drop',e=>{e.preventDefault();stage.classList.remove('drag');readFile(e.dataTransfer.files[0])});
window.addEventListener('paste',e=>{for(const it of e.clipboardData.items){if(it.type.startsWith('image/')){readFile(it.getAsFile());break}}});

function resize(){cv.width=Math.round(W*zoom);cv.height=Math.round(H*zoom);draw()}
$('zoom').onchange=e=>{zoom=+e.target.value;resize()};

// ---------- detecção ----------
function detect(){
  if(!imgData)return;
  const thr=+$('pThr').value,minL=+$('pMinL').value,tmin=+$('pTmin').value,tmax=+$('pTmax').value,gapT=+$('pGap').value,marg=+$('pMarg').value;
  const dark=new Uint8Array(W*H);
  for(let i=0,j=0;i<W*H;i++,j+=4){const r=imgData[j],g=imgData[j+1],b=imgData[j+2];
    const mx=Math.max(r,g,b),mn=Math.min(r,g,b);dark[i]=((r+g+b)/3<thr&&mx-mn<70)?1:0}
  // segmentos longos ao longo de um eixo
  function segs(vertical){const out=[],A=vertical?W:H,B=vertical?H:W;
    for(let a=0;a<A;a++){let b=0;while(b<B){const v=vertical?dark[b*W+a]:dark[a*W+b];
      if(v){const s=b;let g=0;while(b<B){const vv=vertical?dark[b*W+a]:dark[a*W+b];if(vv)g=0;else if(++g>gapT)break;b++}
        const e=b-g;if(e-s>=minL)out.push([a,s,e])}else b++}}
    return out}
  function group(sg,vertical){
    const lines=[];
    for(const [a,s,e] of sg){let hit=null;
      for(let i=lines.length-1;i>=0;i--){const L=lines[i];if(a-L.a1>1)continue;if(Math.abs(s-L.s)<6&&Math.abs(e-L.e)<6){hit=L;break}}
      if(hit){hit.a1=a;hit.s=Math.min(hit.s,s);hit.e=Math.max(hit.e,e)}else lines.push({a0:a,a1:a,s,e})}
    const thin=lines.filter(L=>L.a1-L.a0<=3).sort((p,q)=>p.a0-q.a0);
    const gs=[];
    for(const L of thin){let hit=null;
      for(const G of gs){if(L.a1-G.a0<=tmax&&Math.abs(L.s-G.s)<10&&Math.abs(L.e-G.e)<10){hit=G;break}}
      if(hit){hit.a1=Math.max(hit.a1,L.a1);hit.n++;hit.s=Math.min(hit.s,L.s);hit.e=Math.max(hit.e,L.e)}
      else gs.push({a0:L.a0,a1:L.a1,s:L.s,e:L.e,n:1})}
    return gs.filter(G=>{const t=G.a1-G.a0;return G.n>=2&&t>=tmin&&t<=tmax}).map(G=>vertical
      ?{o:'V',x0:G.a0,x1:G.a1,y0:G.s,y1:G.e}:{o:'H',x0:G.s,x1:G.e,y0:G.a0,y1:G.a1})}
  let gs=[...group(segs(true),true),...group(segs(false),false)];
  gs=gs.filter(g=>g.x0>=marg&&g.y0>=marg&&g.x1<=W-marg&&g.y1<=H-marg);
  // remove duplicadas contidas umas nas outras
  gs.sort((a,b)=>area(b)-area(a));
  const keep=[];for(const g of gs){if(!keep.some(K=>K.o===g.o&&inter(K,g)>0.6*area(g)))keep.push(g)}
  gondolas=keep;
  pontas=[];sel=null;selG=null;
  for(const g of gondolas)for(const end of [0,1])addAtEnd(g,end,0);
  renumber();
  $('status').innerHTML=`<b>${gondolas.length}</b> gôndolas e <b>${pontas.length}</b> pontas detectadas. Revise, apague as que não existem e adicione as que faltam.`;
  draw();
}
function area(g){return (g.x1-g.x0+1)*(g.y1-g.y0+1)}
function inter(a,b){const w=Math.min(a.x1,b.x1)-Math.max(a.x0,b.x0),h=Math.min(a.y1,b.y1)-Math.max(a.y0,b.y0);return w>0&&h>0?w*h:0}
function addAtEnd(g,end,tipo){const sz=sizeFor(tipo,g.o);let x,y;
  const fora=$('pPos').value==='fora';
  if(g.o==='V'){x=(g.x0+g.x1)/2-sz.w/2;y=fora?(end?g.y1+1:g.y0-sz.h):(end?g.y1-sz.h:g.y0)}
  else{y=(g.y0+g.y1)/2-sz.h/2;x=fora?(end?g.x1+1:g.x0-sz.w):(end?g.x1-sz.w:g.x0)}
  const p={id:nextId++,num:0,tipo,o:g.o,x:Math.round(x),y:Math.round(y),w:sz.w,h:sz.h};
  if(collides(p))return null;
  pontas.push(p);return p}
function renumber(){const band=15;pontas.sort((a,b)=>{const dy=Math.round((a.y+a.h/2)/band)-Math.round((b.y+b.h/2)/band);return dy||(a.x-b.x)});pontas.forEach((p,i)=>p.num=i+1)}

// ---------- regras de posição ----------
// duas pontas não podem ocupar o mesmo lugar (qualquer sobreposição de área bloqueia; encostar é permitido)
function overlaps(a,b){return a.x<b.x+b.w&&b.x<a.x+a.w&&a.y<b.y+b.h&&b.y<a.y+a.h}
function collides(r,ignore){return pontas.some(q=>q!==r&&q.id!==r.id&&!(ignore&&ignore.has(q))&&overlaps(r,q))}
function blocked(){toast('Já existe uma ponta nesse lugar')}
// tenta mover a ponta; se bater em outra, desliza só no eixo livre
function tryMove(p,nx,ny){
  for(const c of [[nx,ny],[nx,p.y],[p.x,ny]]){if(c[0]===p.x&&c[1]===p.y)continue;
    if(!collides({...p,x:c[0],y:c[1]})){p.x=c[0];p.y=c[1];return true}}
  return false}
// pontas que pertencem a uma gôndola (centro dentro do contorno, com folga)
function membersOf(g){const m=18;return pontas.filter(p=>{const cx=p.x+p.w/2,cy=p.y+p.h/2;return cx>=g.x0-m&&cx<=g.x1+m&&cy>=g.y0-m&&cy<=g.y1+m})}
// move a gôndola junto com as pontas dela; bloqueia se alguma ponta cair sobre outra
function tryMoveG(g,dx,dy,mem){mem=mem||membersOf(g);const set=new Set(mem);
  for(const [ax,ay] of [[dx,dy],[dx,0],[0,dy]]){if(!ax&&!ay)continue;
    if(!mem.some(p=>collides({...p,x:p.x+ax,y:p.y+ay},set))){
      g.x0+=ax;g.x1+=ax;g.y0+=ay;g.y1+=ay;for(const p of mem){p.x+=ax;p.y+=ay}return [ax,ay]}}
  return null}
function overlapSet(){const s=new Set();for(let i=0;i<pontas.length;i++)for(let j=i+1;j<pontas.length;j++)if(overlaps(pontas[i],pontas[j])){s.add(pontas[i]);s.add(pontas[j])}return s}

// ---------- desenho ----------
function cssVar(n,f){return getComputedStyle(document.documentElement).getPropertyValue(n).trim()||f}
function draw(){
  ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,cv.width,cv.height);ctx.setTransform(zoom,0,0,zoom,0,0);
  if(img)ctx.drawImage(img,0,0);
  if($('showG').checked){ctx.lineWidth=1/zoom;ctx.setLineDash([3/zoom,2/zoom]);ctx.strokeStyle='rgba(0,89,168,.8)';
    for(const g of gondolas)if(g!==selG)ctx.strokeRect(g.x0-1,g.y0-1,g.x1-g.x0+2,g.y1-g.y0+2);ctx.setLineDash([]);
    if(selG){ctx.fillStyle='rgba(0,89,168,.14)';ctx.fillRect(selG.x0-1,selG.y0-1,selG.x1-selG.x0+2,selG.y1-selG.y0+2);
      ctx.strokeStyle='#0059a8';ctx.lineWidth=2/zoom;ctx.strokeRect(selG.x0-1,selG.y0-1,selG.x1-selG.x0+2,selG.y1-selG.y0+2)}}
  const bad=overlapSet(),red=cssVar('--kl-sel','#e0002a');
  ctx.font='700 9px Roboto, Arial, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';
  for(const p of pontas){const t=tipoOf(p);ctx.fillStyle=t.cor;ctx.globalAlpha=.85;ctx.fillRect(p.x,p.y,p.w,p.h);ctx.globalAlpha=1;
    ctx.strokeStyle='rgba(0,0,0,.55)';ctx.lineWidth=1/zoom;ctx.strokeRect(p.x,p.y,p.w,p.h);
    ctx.fillStyle='#111';ctx.fillText(p.num,p.x+p.w/2,p.y+p.h/2+.5);
    if(bad.has(p)){ctx.strokeStyle=red;ctx.lineWidth=1.5/zoom;ctx.setLineDash([2/zoom,1.5/zoom]);ctx.strokeRect(p.x-1,p.y-1,p.w+2,p.h+2);ctx.setLineDash([])}
    if(p===sel){ctx.strokeStyle=red;ctx.lineWidth=2/zoom;ctx.strokeRect(p.x-2,p.y-2,p.w+4,p.h+4)}}
  $('overlapWarn').classList.toggle('d-none',!bad.size);
  if(bad.size)$('overlapWarn').textContent=`${bad.size} pontas estão sobrepostas (contorno vermelho tracejado). Mova ou exclua uma delas.`;
  renderTable();renderSel();
}

// ---------- interação ----------
function pt(e){const r=cv.getBoundingClientRect();return {x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}
function hit(x,y){for(let i=pontas.length-1;i>=0;i--){const p=pontas[i];if(x>=p.x-2&&x<=p.x+p.w+2&&y>=p.y-2&&y<=p.y+p.h+2)return p}return null}
function hitG(x,y){if(!$('showG').checked)return null;const m=3;let best=null;
  for(const g of gondolas)if(x>=g.x0-m&&x<=g.x1+m&&y>=g.y0-m&&y<=g.y1+m){if(!best||area(g)<area(best))best=g}return best}
let drag=null,dragG=null,selG=null,lastBlock=0;
function blockedOnce(){if(Date.now()-lastBlock>1500){lastBlock=Date.now();blocked()}}
cv.addEventListener('pointerdown',e=>{const {x,y}=pt(e);const p=hit(x,y);
  if(p&&!addMode){sel=p;selG=null;drag={dx:x-p.x,dy:y-p.y};cv.setPointerCapture(e.pointerId);draw();return}
  if(!addMode){const g=hitG(x,y);sel=null;
    if(g){selG=g;dragG={sx:x,sy:y,mx:0,my:0,mem:membersOf(g)};cv.setPointerCapture(e.pointerId);cv.style.cursor='grabbing'}
    else selG=null;
    draw();return}
  const tipo=sel?sel.tipo:0;let o=orientMode==='auto'?'V':orientMode;
  const g=gondolas.find(g=>x>=g.x0-15&&x<=g.x1+15&&y>=g.y0-15&&y<=g.y1+15);
  if(g&&orientMode==='auto')o=g.o;
  const sz=sizeFor(tipo,o);let nx=x-sz.w/2,ny=y-sz.h/2;
  if(g){if(g.o==='V')nx=(g.x0+g.x1)/2-sz.w/2;else ny=(g.y0+g.y1)/2-sz.h/2}
  const np={id:nextId++,num:Math.max(0,...pontas.map(q=>q.num))+1,tipo,o,x:Math.round(nx),y:Math.round(ny),w:sz.w,h:sz.h};
  if(collides(np)){blocked();return}
  pontas.push(np);sel=np;selG=null;draw()});
cv.addEventListener('pointermove',e=>{const {x,y}=pt(e);
  if(drag&&sel){const nx=Math.round(x-drag.dx),ny=Math.round(y-drag.dy);
    if((nx!==sel.x||ny!==sel.y)&&!tryMove(sel,nx,ny))blockedOnce();draw();return}
  if(dragG&&selG){const dx=Math.round(x-dragG.sx)-dragG.mx,dy=Math.round(y-dragG.sy)-dragG.my;
    if(dx||dy){const r=tryMoveG(selG,dx,dy,dragG.mem);
      if(r){dragG.mx+=r[0];dragG.my+=r[1]}else blockedOnce();draw()}return}
  cv.style.cursor=addMode?'crosshair':hit(x,y)?'move':hitG(x,y)?'grab':'default'});
cv.addEventListener('pointerup',()=>{drag=null;if(dragG){dragG=null;cv.style.cursor='grab'}});
function rotate(p){if(!p)return;const cx=p.x+p.w/2,cy=p.y+p.h/2;
  const r={...p,w:p.h,h:p.w};r.x=Math.round(cx-r.w/2);r.y=Math.round(cy-r.h/2);
  if(collides(r)){blocked();return}Object.assign(p,r,{o:p.o==='V'?'H':'V'});draw()}
function del(p){if(!p)return;pontas=pontas.filter(q=>q!==p);sel=null;draw()}
function delG(g){if(!g)return;gondolas=gondolas.filter(q=>q!==g);selG=null;draw();toast('Contorno da gôndola removido. As pontas continuam.')}
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
  const s=e.shiftKey?5:1;
  if(e.key==='Delete'||e.key==='Backspace'){if(sel)del(sel);else delG(selG);e.preventDefault()}
  else if(e.key==='r'||e.key==='R')rotate(sel);
  else if(e.key==='a'||e.key==='A')setAdd(!addMode);
  else if(e.key==='Escape'){setAdd(false);sel=null;selG=null;draw()}
  else if((sel||selG)&&e.key.startsWith('Arrow')){e.preventDefault();
    const dx=e.key==='ArrowLeft'?-s:e.key==='ArrowRight'?s:0,dy=e.key==='ArrowUp'?-s:e.key==='ArrowDown'?s:0;
    const ok=sel?tryMove(sel,sel.x+dx,sel.y+dy):tryMoveG(selG,dx,dy);if(!ok)blocked();draw()}});

function setAdd(v){addMode=v;$('btnAdd').classList.toggle('active',v);$('btnAdd').setAttribute('aria-pressed',v)}
$('btnAdd').onclick=()=>setAdd(!addMode);
$('btnOrient').onclick=()=>{orientMode={auto:'V',V:'H',H:'auto'}[orientMode];
  $('btnOrient').textContent='Orientação: '+{auto:'auto',V:'vertical',H:'horizontal'}[orientMode]};
$('btnDetect').onclick=()=>{detect();toast('Detecção concluída')};
$('btnRenum').onclick=()=>{renumber();draw();toast('Pontas renumeradas')};
$('btnClear').onclick=function(){if(this.dataset.c){pontas=[];gondolas=[];sel=null;selG=null;draw();this.textContent='Limpar';delete this.dataset.c}
  else{this.dataset.c=1;this.textContent='Confirmar limpar';setTimeout(()=>{this.textContent='Limpar';delete this.dataset.c},2500)}};
$('btnRot').onclick=()=>rotate(sel);$('btnDel').onclick=()=>del(sel);
$('showG').onchange=draw;

// ---------- painel ----------
function renderSel(){const on=!!sel;for(const id of ['eNum','eTipo','eX','eY','eH','eW','btnCopyOne','btnRot','btnDel'])$(id).disabled=!on;
  $('eTipo').innerHTML=tipos.map((t,i)=>`<option value="${i}">${esc(t.nome)}</option>`).join('');
  if(!on){$('selInfo').textContent='Nenhuma selecionada';for(const id of ['eNum','eX','eY','eH','eW'])$(id).value='';return}
  const v=erp(sel);$('selInfo').textContent=sel.o==='V'?'Gôndola vertical':'Gôndola horizontal';
  $('eNum').value=sel.num;$('eTipo').value=sel.tipo;$('eX').value=v.X;$('eY').value=v.Y;$('eH').value=v.H;$('eW').value=v.W}
function onEdit(){if(!sel)return;sel.num=+$('eNum').value;
  const nt=+$('eTipo').value;let r;
  if(nt!==sel.tipo){const sz=sizeFor(nt,sel.o);const cx=sel.x+sel.w/2,cy=sel.y+sel.h/2;r={...sel,tipo:nt,w:sz.w,h:sz.h,x:Math.round(cx-sz.w/2),y:Math.round(cy-sz.h/2)}}
  else r={...sel,...fromErp({X:+$('eX').value,Y:+$('eY').value,H:+$('eH').value,W:+$('eW').value})};
  if(collides(r)){blocked();draw();return}
  Object.assign(sel,r);draw()}

for(const id of ['eNum','eTipo','eX','eY','eH','eW'])$(id).addEventListener('change',onEdit);
function esc(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function sorted(){return [...pontas].sort((a,b)=>a.num-b.num)}
function renderTable(){const tb=$('tb');$('count').textContent=pontas.length+' pontas';
  if(!pontas.length){tb.innerHTML=`<tr><td colspan="6" class="text-center text-body-secondary py-4 font-sans">Nenhuma ponta ainda. Clique em <b>Detectar pontas</b> ou em <b>+ Adicionar</b>.</td></tr>`;return}
  tb.innerHTML=sorted().map(p=>{const v=erp(p),t=tipoOf(p);return `<tr data-id="${p.id}" class="${p===sel?'table-active':''}"><td>${p.num}</td><td>${v.X}</td><td>${v.Y}</td><td>${v.H}</td><td>${v.W}</td><td class="text-start font-sans"><span class="sw" style="background:${t.cor}"></span>${esc(t.nome)}</td></tr>`}).join('')}
$('tb').addEventListener('click',e=>{const tr=e.target.closest('tr[data-id]');if(!tr)return;sel=pontas.find(p=>p.id==tr.dataset.id);selG=null;draw();
  const s=stage;s.scrollTo({left:sel.x*zoom-s.clientWidth/2,top:sel.y*zoom-s.clientHeight/2,behavior:'smooth'})});
function copy(text,msg){const done=()=>toast(msg);const fb=()=>{const o=$('out');o.classList.remove('d-none');o.value=text;o.focus();o.select();toast('Selecionado: use Ctrl+C')};
  try{navigator.clipboard.writeText(text).then(done,fb)}catch(e){fb()}}
$('btnTSV').onclick=()=>{const rows=[['Id','X','Y','Height','Width','Tipo','Desenho']];
  for(const p of sorted()){const v=erp(p);rows.push([p.num,v.X,v.Y,v.H,v.W,tipoOf(p).nome,'Retângulo'])}
  copy(rows.map(r=>r.join('\t')).join('\n'),'Tabela copiada. Cole no Excel')};
$('btnJSON').onclick=()=>copy(JSON.stringify(sorted().map(p=>({numero:p.num,tipo:tipoOf(p).nome,desenho:'Retângulo',...erp(p)})),null,2),'JSON copiado');
$('btnCopyOne').onclick=()=>{const v=erp(sel);copy(`${v.X}\t${v.Y}\t${v.H}\t${v.W}`,'X Y H W copiados')};

// ---------- tipos ----------
function renderTypes(){$('types').innerHTML=tipos.map((t,i)=>`<div class="d-flex gap-2 align-items-center" data-i="${i}">
<input type="color" class="form-control form-control-color form-control-sm flex-shrink-0" value="${t.cor}" title="Cor" aria-label="Cor" data-f="cor" id="tc${i}">
<input class="form-control form-control-sm" value="${esc(t.nome)}" data-f="nome" aria-label="Nome do tipo" id="tn${i}">
<input type="number" class="form-control form-control-sm num" value="${t.frente}" data-f="frente" aria-label="Frente" title="Frente" id="tf${i}">
<input type="number" class="form-control form-control-sm num" value="${t.prof}" data-f="prof" aria-label="Profundidade" title="Profundidade" id="tp${i}">
<button type="button" class="btn btn-sm btn-outline-danger flex-shrink-0" data-del="${i}" aria-label="Remover tipo" ${tipos.length<2?'disabled':''}>&times;</button></div>`).join('')}
$('types').addEventListener('change',e=>{const row=e.target.closest('[data-i]');if(!row)return;const i=+row.dataset.i,f=e.target.dataset.f;
  tipos[i][f]=(f==='frente'||f==='prof')?+e.target.value:e.target.value;
  if(f==='frente'||f==='prof')for(const p of pontas)if(p.tipo===i){const sz=sizeFor(i,p.o);p.w=sz.w;p.h=sz.h}
  store.set('pg_tipos',tipos);draw()});
$('types').addEventListener('click',e=>{const d=e.target.closest('[data-del]')?.dataset.del;if(d==null)return;const i=+d;tipos.splice(i,1);
  for(const p of pontas){if(p.tipo===i)p.tipo=0;else if(p.tipo>i)p.tipo--}store.set('pg_tipos',tipos);renderTypes();draw()});
$('btnAddType').onclick=()=>{tipos.push({nome:'Novo tipo',cor:'#e5484d',frente:20,prof:12});store.set('pg_tipos',tipos);renderTypes();draw()};

function updScale(){const s=k();$('scaleInfo').textContent=`Planta com ${W}×${H} px. Escala aplicada: ${s.toFixed(3)}. X e Y são o canto superior esquerdo da ponta.`;draw()}
for(const id of ['erpW','offX','offY'])$(id).addEventListener('input',updScale);

renderTypes();
if(SAMPLE)loadImage(SAMPLE,()=>{detect();$('status').innerHTML+=' Planta da loja 0214 - AL-MAC-Pq.ShopMaceio.'});
else{resize();$('status').textContent='Abra a planta da loja (a mesma imagem cadastrada no ERP) para começar.'}

$('pPos').addEventListener('change',()=>{detect();toast('Pontas reposicionadas')});
$('btnSaveAll').onclick=()=>toast(`Na versão final, as ${pontas.length} pontas são gravadas no ERP de uma vez`);

$('btnAddTop').onclick=()=>{setAdd(true);toast('Clique na planta para posicionar a ponta')};
